1	import { DUEL_BUTTONS, DUEL_INPUT, movesetVersion, THROW_CHORD_PARTNER, type DuelMove, type DuelMoveset } from "@pirate-sea-race/content/moves";
2	import { clampInt, divTrunc } from "../fixed.js";
3	import { overlaps, worldBox, type Facing } from "./boxes.js";
4	import { directions, sanitizeDuelInput, type DuelInputs } from "./input.js";
5	import {
6	  canAct,
7	  findMove,
8	  moveDuration,
9	  type DuelConfig,
10	  type DuelEvent,
11	  type DuelResult,
12	  type DuelState,
13	  type FighterState,
14	  type InputBuffer,
15	  type PlayerIndex,
16	  type Stance,
17	} from "./state.js";
18	
19	/** One player's input for this frame, read against last frame's held buttons. */
20	interface FrameInput {
21	  readonly bits: number;
22	  readonly h: -1 | 0 | 1;
23	  readonly v: -1 | 0 | 1;
24	  readonly buffer: InputBuffer;
25	}
26	
27	/** What one fighter's move does to the other this frame, detected against the start-of-frame state. */
28	interface Contact {
29	  readonly kind: "hit" | "block" | "grab";
30	  readonly move: DuelMove;
31	  /** The defender's stance at contact. */
32	  readonly stance: Stance;
33	}
34	
35	type Pair<T> = readonly [T, T];
36	
37	const OTHER = [1, 0] as const;
38	
39	/** One value per fighter, player one's first. */
40	function both<T>(each: (index: PlayerIndex) => T): Pair<T> {
41	  return [each(0), each(1)];
42	}
43	
44	/**
45	 * Advances the duel by one 60 Hz frame (order of operations in docs/duel.md):
46	 *
47	 * 1. read both inputs (opposite directions cancel; newly pressed buttons enter the 4-frame buffer);
48	 * 2. detect every hit, block and grab of the frame against the start-of-frame state of both fighters;
49	 * 3. settle same-frame interactions (throw against throw breaks both; a strike that hits or is blocked beats a throw);
50	 * 4. apply all results together, damage and stamina from start-of-frame values; fighters not struck advance their
51	 *    action (a light or heavy may still become the throw inside the chord window) or start a new one from their input;
52	 * 5. move, apply gravity, keep fighters inside the walls and apart;
53	 * 6. regenerate stamina, then decide KO, timeout and overtime from both fighters' health.
54	 *
55	 * Neither fighter is processed "first": every decision for one fighter reads only the start-of-frame state and the
56	 * frame's inputs. The input state is never mutated. A finished duel only advances its frame counter.
57	 */
58	export function stepDuel(config: DuelConfig, state: DuelState, inputs: DuelInputs): DuelState {
59	  const { moveset } = config;
60	  const version = movesetVersion(moveset);
61	  if (state.movesetVersion !== version) {
62	    throw new Error(`the duel runs on moveset ${state.movesetVersion}, not ${version}`);
63	  }
64	  const frame = state.frame + 1;
65	  if (state.result !== null) return { ...state, frame, events: [] };
66	
67	  const fighters = state.fighters;
68	  const input: Pair<FrameInput> = [readInput(moveset, fighters[0], inputs[0]), readInput(moveset, fighters[1], inputs[1])];
69	
70	  // 2. Detection, each against the same start-of-frame state.
71	  let contacts: Pair<Contact | null> = [detect(moveset, fighters, 0, input), detect(moveset, fighters, 1, input)];
72	
73	  // 3. Same-frame interactions.
74	  const clash = contacts[0]?.kind === "grab" && contacts[1]?.kind === "grab";
75	  if (clash) {
76	    contacts = [null, null];
77	  } else {
78	    // A grab fails against a strike that hits or is blocked on the same frame; an active hitbox that misses does not
79	    // stop it.
80	    const strikes = (contact: Contact | null) => contact !== null && contact.kind !== "grab";
81	    contacts = [
82	      contacts[0]?.kind === "grab" && strikes(contacts[1]) ? null : contacts[0],
83	      contacts[1]?.kind === "grab" && strikes(contacts[0]) ? null : contacts[1],
84	    ];
85	  }
86	  const escape: Pair<boolean> = [escapes(fighters[0], input[0]), escapes(fighters[1], input[1])];
87	  const throwBreak = clash || escape[0] || escape[1];
88	
89	  // Displacement from pushback and throw breaks, from start-of-frame positions.
90	  const shift = [0, 0];
91	  const minX = moveset.fighter.pushbox.halfWidth;
92	  const maxX = moveset.arena.width - minX;
93	  for (const attacker of [0, 1] as const) {
94	    const contact = contacts[attacker];
95	    if (contact === null || contact.kind === "grab") continue;
96	    const defender = OTHER[attacker];
97	    const def = fighters[defender];
98	    const push = contact.kind === "hit" ? contact.move.hitPushback : contact.move.blockPushback;
99	    const direction = awayFrom(def, fighters[attacker]);
100	    const target = clampInt(def.x + direction * push, minX, maxX);
101	    shift[defender]! += target - def.x;
102	    // Against a wall, the rest of the pushback moves the attacker back instead.
103	    shift[attacker]! -= direction * (push - Math.abs(target - def.x));
104	  }
105	  if (throwBreak) {
106	    for (const index of [0, 1] as const) {
107	      shift[index]! += awayFrom(fighters[index], fighters[OTHER[index]]) * moveset.fighter.throwBreakPushback;
108	    }
109	  }
110	
111	  // 4. Apply results and advance actions.
112	  const events: DuelEvent[] = [];
113	  const spent = [false, false];
114	  const next = both((index): FighterState => {
115	    const self = fighters[index];
116	    const opponent = fighters[OTHER[index]];
117	    const incoming = contacts[OTHER[index]];
118	    const outgoing = contacts[index];
119	    const own = input[index];
120	    let fighter: FighterState = { ...self, held: own.bits, buffer: own.buffer };
121	    if (throwBreak) {
122	      // Two throws on one frame, or an escape: both fighters recover apart with no damage.
123	      if (clash) events.push({ kind: "throw-clash", attacker: index, moveId: self.moveId ?? "", damage: 0 });
124	      if (escape[OTHER[index]]) events.push({ kind: "throw-escape", attacker: index, moveId: moveset.commands.throw, damage: 0 });
125	      return startTimed(fighter, "throw-break", moveset.fighter.throwBreakFrames);
126	    }
127	    if (incoming !== null) {
128	      const attacker = OTHER[index];
129	      const result = react(moveset, fighter, incoming, attacker);
130	      events.push(result.event);
131	      if (incoming.kind === "block") spent[index] = true;
132	      return result.fighter;
133	    }
134	    if (outgoing !== null) fighter = { ...fighter, moveHit: true };
135	    if (fighter.action === "thrown") {
136	      if (fighter.timer > 0) return { ...fighter, timer: fighter.timer - 1, actionFrame: fighter.actionFrame + 1 };
137	      // The escape window ran out: the throw lands.
138	      const move = findMove(moveset, moveset.commands.throw);
139	      const damage = scaledDamage(moveset, move.damage, fighter.combo);
140	      events.push({ kind: "throw", attacker: OTHER[index], moveId: move.timing.id, damage });
141	      return {
142	        ...startTimed(fighter, "knockdown", move.hitstun),
143	        health: Math.max(0, fighter.health - damage),
144	        combo: fighter.combo + 1,
145	      };
146	    }
147	    if (!canAct(self)) return chordThrow(moveset, fighter) ?? progress(moveset, fighter);
148	    const started = choose(moveset, fighter, opponent, own);
149	    if (started.action === "dash" || started.action === "backdash") spent[index] = true;
150	    return started;
151	  });
152	
153	  // 5. Movement: velocities, gravity and landing, walls, then pushboxes.
154	  const moved = both((index) => move(moveset, next[index], shift[index]!));
155	  const separated = separate(moveset, fighters, moved);
156	
157	  // 6. Stamina regeneration, then the result.
158	  const rules = moveset.rules;
159	  const final = both((index): FighterState => {
160	    const fighter = separated[index];
161	    if (spent[index]) return { ...fighter, staminaIdle: 0 };
162	    const idle = fighter.staminaIdle + 1;
163	    const regenerates =
164	      idle > rules.staminaRegenDelayFrames && (idle - rules.staminaRegenDelayFrames) % rules.staminaRegenIntervalFrames === 0;
165	    return { ...fighter, staminaIdle: idle, stamina: regenerates ? Math.min(rules.maxStamina, fighter.stamina + 1) : fighter.stamina };
166	  });
167	
168	  const result = decide(moveset, state, frame, final);
169	  return {
170	    ...state,
171	    frame,
172	    phase: result === null ? (state.phase === "round" && frame >= rules.roundFrames ? "overtime" : state.phase) : "over",
173	    fighters: final,
174	    events,
175	    result,
176	  };
177	}
178	
179	function readInput(moveset: DuelMoveset, fighter: FighterState, raw: number): FrameInput {
180	  const bits = sanitizeDuelInput(raw);
181	  const pressed = bits & ~fighter.held;
182	  const buffer = Object.fromEntries(
183	    DUEL_BUTTONS.map((button) => [
184	      button,
185	      (pressed & DUEL_INPUT[button]) !== 0 ? moveset.rules.inputBufferFrames : Math.max(0, fighter.buffer[button] - 1),
186	    ]),
187	  ) as unknown as InputBuffer;
188	  return { bits, ...directions(bits), buffer };
189	}
190	
191	/** -1 or 1: the direction pointing from `other` to `self` (behind `self`'s facing when they share an x). */
192	function awayFrom(self: FighterState, other: FighterState): Facing {
193	  return self.x > other.x ? 1 : self.x < other.x ? -1 : self.facing === 1 ? -1 : 1;
194	}
195	
196	/** The move frame a fighter executes this frame, or 0 when it is not attacking. */
197	function currentMoveFrame(fighter: FighterState): number {
198	  return fighter.action === "attack" ? fighter.actionFrame + 1 : 0;
199	}
200	
201	function isActiveFrame(move: DuelMove, moveFrame: number): boolean {
202	  return moveFrame > move.timing.startup && moveFrame <= move.timing.startup + move.timing.active;
203	}
204	
205	function isAirborne(fighter: FighterState): boolean {
206	  return fighter.y > 0 || fighter.vy > 0 || fighter.action === "jump";
207	}
208	
209	/** A free or blocking fighter changes stance with this frame's input; anyone else keeps the one they had. */
210	function stanceOf(fighter: FighterState, input: FrameInput): Stance {
211	  if (isAirborne(fighter)) return "airborne";
212	  if (canAct(fighter) || fighter.action === "blockstun") return input.v === -1 ? "crouching" : "standing";
213	  return fighter.crouching ? "crouching" : "standing";
214	}
215	
216	function detect(moveset: DuelMoveset, fighters: Pair<FighterState>, attacker: PlayerIndex, input: Pair<FrameInput>): Contact | null {
217	  const att = fighters[attacker];
218	  if (att.action !== "attack" || att.moveId === null || att.moveHit) return null;
219	  const move = findMove(moveset, att.moveId);
220	  if (!isActiveFrame(move, currentMoveFrame(att))) return null;
221	  const defender = OTHER[attacker];
222	  const def = fighters[defender];
223	  const stance = stanceOf(def, input[defender]);
224	  const reaches = () =>
225	    overlaps(worldBox(move.hitbox, att.x, att.y, att.facing), worldBox(moveset.fighter.hurtboxes[stance], def.x, def.y, def.facing));
226	
227	  if (move.kind === "throw") {
228	    const throwable =
229	      stance !== "airborne" && !["hitstun", "blockstun", "thrown", "throw-break", "knockdown"].includes(def.action);
230	    return throwable && reaches() ? { kind: "grab", move, stance } : null;
231	  }
232	  if (def.action === "thrown" || def.action === "knockdown") return null;
233	  if (def.action === "attack" && def.moveId !== null && findMove(moveset, def.moveId).strikeInvulnerable >= currentMoveFrame(def)) {
234	    return null;
235	  }
236	  // Crouching avoids highs whether or not it guards.
237	  if (move.guard === "high" && stance === "crouching") return null;
238	  if (!reaches()) return null;
239	  const guarding =
240	    stance !== "airborne" &&
241	    (canAct(def) || def.action === "blockstun") &&
242	    input[defender].h === awayFrom(def, att) &&
243	    (stance === "standing" ? move.guard === "high" || move.guard === "mid" : move.guard === "low");
244	  return { kind: guarding ? "block" : "hit", move, stance };
245	}
246	
247	/** A thrown fighter escapes by pressing light and heavy (both within the buffer) while the window is open. */
248	function escapes(fighter: FighterState, input: FrameInput): boolean {
249	  return fighter.action === "thrown" && fighter.timer > 0 && input.buffer.light > 0 && input.buffer.heavy > 0;
250	}
251	
252	function scaledDamage(moveset: DuelMoveset, damage: number, comboHits: number): number {
253	  const scaling = moveset.rules.comboScaling;
254	  const percent = scaling[Math.min(comboHits, scaling.length - 1)]!;
255	  return divTrunc(damage * percent, 100);
256	}
257	
258	/** Starts a timed action lasting `frames` frames, the current one included. */
259	function startTimed(fighter: FighterState, action: FighterState["action"], frames: number): FighterState {
260	  return {
261	    ...fighter,
262	    action,
263	    actionFrame: 1,
264	    timer: Math.max(0, frames - 1),
265	    moveId: null,
266	    moveHit: false,
267	    vx: 0,
268	    vy: fighter.y > 0 ? Math.min(fighter.vy, 0) : 0,
269	    crouching: false,
270	  };
271	}
272	
273	function react(moveset: DuelMoveset, fighter: FighterState, contact: Contact, attacker: PlayerIndex): { fighter: FighterState; event: DuelEvent } {
274	  const { move, stance } = contact;
275	  const { rules } = moveset;
276	  const moveId = move.timing.id;
277	  const crouching = stance === "crouching";
278	  if (contact.kind === "grab") {
279	    // The escape window is the ten frames after the grab; presses from before it do not count.
280	    const held = startTimed(fighter, "thrown", rules.throwEscapeFrames + 1);
281	    return {
282	      fighter: { ...held, combo: 0, buffer: { ...held.buffer, light: 0, heavy: 0 } },
283	      event: { kind: "grab", attacker, moveId, damage: 0 },
284	    };
285	  }
286	  if (contact.kind === "block") {
287	    const cost = move.guardStaminaCost;
288	    if (cost > fighter.stamina) {
289	      const staggered = startTimed(fighter, "stagger", rules.guardBreakStaggerFrames);
290	      return {
291	        fighter: { ...staggered, combo: 0, stamina: Math.min(rules.maxStamina, fighter.stamina + rules.guardBreakStaminaRestore) },
292	        event: { kind: "guard-break", attacker, moveId, damage: 0 },
293	      };
294	    }
295	    return {
296	      fighter: { ...startTimed(fighter, "blockstun", move.blockstun), combo: 0, crouching, stamina: fighter.stamina - cost },
297	      event: { kind: "block", attacker, moveId, damage: 0 },
298	    };
299	  }
300	  // A fighter still in hitstun continues the combo; a free one starts a new one.
301	  const comboHits = fighter.action === "hitstun" && !canAct(fighter) ? fighter.combo : 0;
302	  const damage = scaledDamage(moveset, move.damage, comboHits);
303	  const combo = comboHits + 1;
304	  const capped = combo >= rules.comboCap;
305	  const struck = startTimed(fighter, capped ? "knockdown" : "hitstun", capped ? rules.forcedRecoveryFrames : move.hitstun);
306	  return {
307	    fighter: {
308	      ...struck,
309	      health: Math.max(0, fighter.health - damage),
310	      combo,
311	      crouching: capped ? false : crouching,
312	      vy: move.launch > 0 ? move.launch : struck.vy,
313	    },
314	    event: { kind: "hit", attacker, moveId, damage },
315	  };
316	}
317	
318	/** One more frame of an action the fighter cannot leave yet. */
319	function progress(moveset: DuelMoveset, fighter: FighterState): FighterState {
320	  const actionFrame = fighter.actionFrame + 1;
321	  const timer = Math.max(0, fighter.timer - 1);
322	  switch (fighter.action) {
323	    case "attack": {
324	      const move = findMove(moveset, fighter.moveId!);
325	      return { ...fighter, actionFrame, timer, vx: advance(move, actionFrame, fighter.facing) };
326	    }
327	    case "dash":
328	    case "backdash":
329	      return { ...fighter, actionFrame, timer };
330	    case "jump":
331	      return { ...fighter, actionFrame };
332	    default:
333	      return { ...fighter, actionFrame, timer, vx: 0 };
334	  }
335	}
336	
337	/**
338	 * The throw chord window (§8, keyboard rollover): a light or heavy move that a free fighter started becomes the throw
339	 * when the other button is pressed within `throwChordFrames` frames of the start, before the move's first active
340	 * frame. The throw keeps the frames already spent, so it lands as if both buttons had gone down together, and a lone
341	 * light or heavy keeps its own startup. `fighter` carries this frame's input buffer; null leaves the move as it is.
342	 */
343	function chordThrow(moveset: DuelMoveset, fighter: FighterState): FighterState | null {
344	  if (fighter.action !== "attack" || fighter.moveId === null || fighter.moveHit) return null;
345	  if (fighter.actionFrame > moveset.rules.throwChordFrames) return null;
346	  const { commands } = moveset;
347	  const command = (Object.keys(THROW_CHORD_PARTNER) as (keyof typeof THROW_CHORD_PARTNER)[]).find((name) => commands[name] === fighter.moveId);
348	  if (command === undefined || fighter.buffer[THROW_CHORD_PARTNER[command]] === 0) return null;
349	  if (fighter.actionFrame >= findMove(moveset, fighter.moveId).timing.startup) return null;
350	  const grab = findMove(moveset, commands.throw);
351	  const actionFrame = fighter.actionFrame + 1;
352	  return {
353	    ...fighter,
354	    moveId: grab.timing.id,
355	    actionFrame,
356	    timer: moveDuration(grab) - actionFrame,
357	    crouching: grab.stance === "crouching",
358	    vx: advance(grab, actionFrame, fighter.facing),
359	    buffer: { ...fighter.buffer, light: 0, heavy: 0 },
360	  };
361	}
362	
363	function advance(move: DuelMove, moveFrame: number, facing: Facing): number {
364	  return move.advance !== 0 && moveFrame <= move.timing.startup + move.timing.active ? move.advance * facing : 0;
365	}
366	
367	/** A free fighter turns to face the opponent and starts whatever its input asks for (§8's priorities). */
368	function choose(moveset: DuelMoveset, self: FighterState, opponent: FighterState, input: FrameInput): FighterState {
369	  const facing: Facing = opponent.x > self.x ? 1 : opponent.x < self.x ? -1 : self.facing;
370	  const { buffer, h, v } = input;
371	  const { commands, fighter: body, rules } = moveset;
372	  const base: FighterState = { ...self, facing, combo: 0, moveHit: false, moveId: null, crouching: false, vy: 0 };
373	  const consume = (...buttons: readonly (keyof InputBuffer)[]): InputBuffer =>
374	    ({ ...buffer, ...Object.fromEntries(buttons.map((button) => [button, 0])) }) as InputBuffer;
375	  const attack = (id: string, used: InputBuffer): FighterState => {
376	    const move = findMove(moveset, id);
377	    return {
378	      ...base,
379	      action: "attack",
380	      moveId: id,
381	      actionFrame: 1,
382	      timer: moveDuration(move) - 1,
383	      crouching: move.stance === "crouching",
384	      vx: advance(move, 1, facing),
385	      buffer: used,
386	    };
387	  };
388	  const forward = h === facing;
389	  const back = h === -facing;
390	
391	  if (buffer.light > 0 && buffer.heavy > 0) return attack(commands.throw, consume("light", "heavy"));
392	  if (buffer.special1 > 0) return attack(commands.special1, consume("special1"));
393	  if (buffer.special2 > 0) return attack(commands.special2, consume("special2"));
394	  if (buffer.heavy > 0) {
395	    return attack(v === -1 ? commands.downHeavy : forward ? commands.forwardHeavy : commands.heavy, consume("heavy"));
396	  }
397	  if (buffer.light > 0) return attack(v === -1 ? commands.downLight : commands.light, consume("light"));
398	  if (buffer.dash > 0 && self.stamina >= rules.dashStaminaCost) {
399	    const frames = back ? body.backdashFrames : body.dashFrames;
400	    return {
401	      ...base,
402	      action: back ? "backdash" : "dash",
403	      actionFrame: 1,
404	      timer: frames - 1,
405	      vx: back ? -facing * body.backdashSpeed : facing * body.dashSpeed,
406	      stamina: self.stamina - rules.dashStaminaCost,
407	      buffer: consume("dash"),
408	    };
409	  }
410	  /** A free action: its frame count carries on while the fighter keeps doing it. */
411	  const free = (action: "idle" | "walk" | "crouch" | "jump", vx: number): FighterState => ({
412	    ...base,
413	    action,
414	    actionFrame: self.action === action ? self.actionFrame + 1 : 1,
415	    timer: 0,
416	    vx,
417	  });
418	  if (v === 1) return { ...free("jump", h * body.jumpSpeedX), vy: body.jumpVelocity };
419	  if (v === -1) return { ...free("crouch", 0), crouching: true };
420	  if (h !== 0) return free("walk", forward ? facing * body.walkForwardSpeed : -facing * body.walkBackSpeed);
421	  return free("idle", 0);
422	}
423	
424	/** Velocity, gravity and landing for one fighter, plus this frame's pushback, kept inside the walls. */
425	function move(moveset: DuelMoveset, fighter: FighterState, shift: number): FighterState {
426	  const minX = moveset.fighter.pushbox.halfWidth;
427	  const maxX = moveset.arena.width - minX;
428	  const x = clampInt(fighter.x + shift + fighter.vx, minX, maxX);
429	  if (fighter.y === 0 && fighter.vy <= 0) return { ...fighter, x, vy: 0 };
430	  const y = fighter.y + fighter.vy;
431	  if (y > 0) return { ...fighter, x, y, vy: fighter.vy - moveset.fighter.gravity };
432	  const landed = { ...fighter, x, y: 0, vx: 0, vy: 0 };
433	  return fighter.action === "jump" ? { ...landed, action: "idle", actionFrame: 1 } : landed;
434	}
435	
436	/**
437	 * Pushes overlapping pushboxes apart, each fighter by half the overlap rounded up, so neither side is favoured; a
438	 * fighter against a wall passes its share to the other. `before` is the start-of-frame state, for ties.
439	 */
440	function separate(moveset: DuelMoveset, before: Pair<FighterState>, fighters: Pair<FighterState>): Pair<FighterState> {
441	  const { halfWidth, height } = moveset.fighter.pushbox;
442	  const [a, b] = fighters;
443	  const dx = Math.abs(a.x - b.x);
444	  if (dx >= 2 * halfWidth || a.y >= b.y + height || b.y >= a.y + height) return fighters;
445	  const aLeft = leftFirst(a, b, before[0], before[1]);
446	  if (aLeft === null) return fighters;
447	  const [left, right] = aLeft ? [a, b] : [b, a];
448	  const half = divTrunc(2 * halfWidth - dx + 1, 2);
449	  const minX = halfWidth;
450	  const maxX = moveset.arena.width - halfWidth;
451	  let leftX = left.x - half;
452	  let rightX = right.x + half;
453	  if (leftX < minX) {
454	    rightX += minX - leftX;
455	    leftX = minX;
456	  }
457	  if (rightX > maxX) {
458	    leftX = Math.max(minX, leftX - (rightX - maxX));
459	    rightX = maxX;
460	  }
461	  const placedLeft = { ...left, x: leftX };
462	  const placedRight = { ...right, x: rightX };
463	  return aLeft ? [placedLeft, placedRight] : [placedRight, placedLeft];
464	}
465	
466	/**
467	 * Whether fighter `a` ends up on the left of `b`: by x, then by start-of-frame x (fighters never pass through each
468	 * other), then by velocity, then by facing (the one facing right is on the left). Every key flips when the arena is
469	 * mirrored, so the answer never depends on the slot; a tie on all of them is `null`, and the two stay where they are.
470	 */
471	function leftFirst(a: FighterState, b: FighterState, a0: FighterState, b0: FighterState): boolean | null {
472	  if (a.x !== b.x) return a.x < b.x;
473	  if (a0.x !== b0.x) return a0.x < b0.x;
474	  if (a.vx !== b.vx) return a.vx < b.vx;
475	  if (a.facing !== b.facing) return a.facing === 1;
476	  return null;
477	}
478	
479	/** KO first (both at once is a draw), then the clock: timeout, overtime, draw (§7). */
480	function decide(moveset: DuelMoveset, state: DuelState, frame: number, fighters: Pair<FighterState>): DuelResult | null {
481	  const [a, b] = fighters;
482	  if (a.health === 0 && b.health === 0) return { winner: null, reason: "double-ko", frame };
483	  if (a.health === 0 || b.health === 0) return { winner: a.health === 0 ? 1 : 0, reason: "ko", frame };
484	  const { roundFrames, overtimeFrames } = moveset.rules;
485	  const compare = (reason: DuelResult["reason"]): DuelResult | null =>
486	    a.health === b.health ? (reason === "timeout" ? null : { winner: null, reason, frame }) : { winner: a.health > b.health ? 0 : 1, reason, frame };
487	  if (state.phase === "round" && frame >= roundFrames) return compare("timeout");
488	  if (state.phase === "overtime" && frame >= roundFrames + overtimeFrames) return compare("overtime");
489	  return null;
490	}
